END;
GO

IF IS_ROLEMEMBER(N'db_datareader', N'devsu_customers_app') = 1
BEGIN
    ALTER ROLE [db_datareader] DROP MEMBER [devsu_customers_app];
END;
GO

IF IS_ROLEMEMBER(N'db_datawriter', N'devsu_customers_app') = 1
BEGIN
    ALTER ROLE [db_datawriter] DROP MEMBER [devsu_customers_app];
END;
GO

GRANT SELECT, INSERT, UPDATE, DELETE
    ON SCHEMA::[customers]
    TO [devsu_customers_app];
GO

IF OBJECT_ID(N'[__EFMigrationsHistory]') IS NULL
BEGIN
    CREATE TABLE [__EFMigrationsHistory] (
        [MigrationId] nvarchar(150) NOT NULL,
        [ProductVersion] nvarchar(32) NOT NULL,
        CONSTRAINT [PK___EFMigrationsHistory] PRIMARY KEY ([MigrationId])
    );
END;
GO

BEGIN TRANSACTION;
GO

IF NOT EXISTS (
    SELECT * FROM [__EFMigrationsHistory]
