IF NOT EXISTS (
    SELECT * FROM [__EFMigrationsHistory]
    WHERE [MigrationId] = N'20260908141830_InitialCustomers'
)
BEGIN
    CREATE TABLE [customers].[People] (
        [Id] uniqueidentifier NOT NULL,
        [Name] nvarchar(100) NOT NULL,
        [Gender] nvarchar(20) NOT NULL,
        [Age] int NOT NULL,
        [Identification] nvarchar(20) NOT NULL,
        [Address] nvarchar(200) NOT NULL,
        [Phone] nvarchar(25) NOT NULL,
        CONSTRAINT [PK_People] PRIMARY KEY ([Id]),
        CONSTRAINT [CK_People_Age] CHECK ([Age] >= 0 AND [Age] <= 130),
        CONSTRAINT [CK_People_Gender] CHECK ([Gender] IN ('Male', 'Female', 'Other'))
    );
END;
GO

IF NOT EXISTS (
    SELECT * FROM [__EFMigrationsHistory]
    WHERE [MigrationId] = N'20260908141830_InitialCustomers'
)
BEGIN
    CREATE TABLE [customers].[Customers] (
        [Id] uniqueidentifier NOT NULL,
        [PasswordHash] nvarchar(512) NOT NULL,
        [IsActive] bit NOT NULL,
        [CreatedAtUtc] datetimeoffset(7) NOT NULL,
        [UpdatedAtUtc] datetimeoffset(7) NOT NULL,
        [DeletedAtUtc] datetimeoffset(7) NULL,
        [AggregateVersion] bigint NOT NULL,
        [RowVersion] rowversion NOT NULL,
        CONSTRAINT [PK_Customers] PRIMARY KEY ([Id]),
        CONSTRAINT [CK_Customers_AggregateVersion] CHECK ([AggregateVersion] >= 1),
        CONSTRAINT [FK_Customers_People_Id] FOREIGN KEY ([Id]) REFERENCES [customers].[People] ([Id]) ON DELETE CASCADE
    );
END;
GO

IF NOT EXISTS (
    SELECT * FROM [__EFMigrationsHistory]
    WHERE [MigrationId] = N'20260908141830_InitialCustomers'
)
BEGIN
    CREATE INDEX [IX_Customers_IsActive_DeletedAtUtc] ON [customers].[Customers] ([IsActive], [DeletedAtUtc]);
END;
GO

IF NOT EXISTS (
    SELECT * FROM [__EFMigrationsHistory]
    WHERE [MigrationId] = N'20260908141830_InitialCustomers'
)
BEGIN
    CREATE UNIQUE INDEX [UX_People_Identification] ON [customers].[People] ([Identification]);
END;
GO

IF NOT EXISTS (
