)
BEGIN
    CREATE TABLE [customers].[OutboxMessages] (
        [EventId] uniqueidentifier NOT NULL,
        [EventType] nvarchar(128) NOT NULL,
        [OccurredAtUtc] datetimeoffset(7) NOT NULL,
        [CorrelationId] nvarchar(128) NOT NULL,
        [AggregateId] uniqueidentifier NOT NULL,
        [AggregateVersion] bigint NOT NULL,
        [Payload] nvarchar(max) NOT NULL,
        [AttemptCount] int NOT NULL,
        [NextAttemptAtUtc] datetimeoffset(7) NOT NULL,
        [LastAttemptAtUtc] datetimeoffset(7) NULL,
        [PublishedAtUtc] datetimeoffset(7) NULL,
        [LeaseId] uniqueidentifier NULL,
        [LeasedUntilUtc] datetimeoffset(7) NULL,
        [LastError] nvarchar(2000) NULL,
        [RowVersion] rowversion NOT NULL,
        CONSTRAINT [PK_OutboxMessages] PRIMARY KEY ([EventId]),
        CONSTRAINT [CK_OutboxMessages_AggregateVersion] CHECK ([AggregateVersion] >= 1),
        CONSTRAINT [CK_OutboxMessages_AttemptCount] CHECK ([AttemptCount] >= 0)
    );
END;
GO

IF NOT EXISTS (
    SELECT * FROM [__EFMigrationsHistory]
    WHERE [MigrationId] = N'20260908172936_AddCustomerOutbox'
)
BEGIN
