GO

IF NOT EXISTS (
    SELECT * FROM [__EFMigrationsHistory]
    WHERE [MigrationId] = N'20260908172936_AddCustomerOutbox'
)
BEGIN
    EXEC(N'CREATE INDEX [IX_OutboxMessages_Pending] ON [customers].[OutboxMessages] ([PublishedAtUtc], [NextAttemptAtUtc], [LeasedUntilUtc]) WHERE [PublishedAtUtc] IS NULL');
END;
GO

IF NOT EXISTS (
    SELECT * FROM [__EFMigrationsHistory]
    WHERE [MigrationId] = N'20260908172936_AddCustomerOutbox'
)
BEGIN
    INSERT INTO [__EFMigrationsHistory] ([MigrationId], [ProductVersion])
    VALUES (N'20260908172936_AddCustomerOutbox', N'8.0.22');
END;
GO

COMMIT;
