BEGIN
    CREATE TABLE [accounts].[AccountMovements] (
        [Id] bigint NOT NULL IDENTITY,
        [AccountNumber] nvarchar(20) NOT NULL,
        [Type] nvarchar(16) NOT NULL,
        [Value] decimal(18,2) NOT NULL,
        [Balance] decimal(18,2) NOT NULL,
        [IdempotencyKey] nvarchar(128) COLLATE Latin1_General_100_BIN2 NOT NULL,
        [RequestFingerprint] char(64) NOT NULL,
        [OccurredAtUtc] datetimeoffset(7) NOT NULL,
        [CreatedAtUtc] datetimeoffset(7) NOT NULL,
        [UpdatedAtUtc] datetimeoffset(7) NOT NULL,
        [RowVersion] rowversion NOT NULL,
        CONSTRAINT [PK_AccountMovements] PRIMARY KEY ([Id]),
        CONSTRAINT [CK_AccountMovements_Balance] CHECK ([Balance] >= 0),
        CONSTRAINT [CK_AccountMovements_Type] CHECK ([Type] IN ('Deposit', 'Withdrawal')),
        CONSTRAINT [CK_AccountMovements_Value] CHECK (([Type] = 'Deposit' AND [Value] > 0) OR ([Type] = 'Withdrawal' AND [Value] < 0)),
        CONSTRAINT [FK_AccountMovements_Accounts_AccountNumber] FOREIGN KEY ([AccountNumber]) REFERENCES [accounts].[Accounts] ([Number]) ON DELETE NO ACTION
    );
END;
